#include <bits/stdc++.h>
using namespace std;
const int dx[] = {0, 1, 0, -1};
const int dy[] = {1, 0, -1, 0};
int main() {
    int h, w, k;
    cin >> h >> w >> k;
    vector<vector<int>> dist(h, vector<int>(w, -1)); // マス (i,j) から始めたときにゴールに到達するまでの移動回数の最小値
    vector<vector<int>> cnt(h, vector<int>(w, 0)); // 隣接するマスのうちdistが決定したマスが何個あるか
    queue<pair<int, int>> que; // distが確定したマスのキュー
    for (int i = 0; i < k; ++i) {
        int x, y;
        cin >> x >> y;
        x--, y--;
        dist[x][y] = 0;
        cnt[x][y] = 4;
        que.emplace(x, y);
    }
    long long ans = 0;
    while (!que.empty()) {
        auto [x, y] = que.front();
        que.pop();
        ans += dist[x][y];
        for (int d = 0; d < 4; ++d) {
            int nx = x + dx[d], ny = y + dy[d];
            if (nx < 0 || nx >= h || ny < 0 || ny >= w)
                continue;
            cnt[nx][ny]++;
            if (dist[nx][ny] == -1 && cnt[nx][ny] == 2) {
                // distが確定しておらず、隣接するマスのうちdistが決定しているマスが2マス存在するためdistが確定する
                dist[nx][ny] = dist[x][y] + 1;
                que.emplace(nx, ny);
            }
        }
    }
    cout << ans << "\n";
}
